WITH _hq_raw AS (SELECT tuple(analytics.orders.created_at, analytics.orders.status, analytics.orders.amount_cents, NULL, analytics.orders.status, NULL) AS _hq_row FROM analytics.orders WHERE analytics.orders.tenant_id = ?),
_hq_source AS (SELECT toDateTime64(assumeNotNull(tupleElement(_hq_row, 1)), 9, 'UTC') AS _hq_time, tupleElement(_hq_row, 2) AS _hq_d0, tupleElement(_hq_row, 3) AS _hq_v0, tupleElement(_hq_row, 4) AS _hq_a0, tupleElement(_hq_row, 5) AS _hq_v1, tupleElement(_hq_row, 6) AS _hq_a1 FROM _hq_raw WHERE isNotNull(tupleElement(_hq_row, 1))),
_hq_bounds AS (SELECT parseDateTime64BestEffort(?, 9, timezoneOf(assumeNotNull((SELECT _hq_time FROM _hq_source LIMIT 0)))) AS _hq_lower, parseDateTime64BestEffort(?, 9, timezoneOf(assumeNotNull((SELECT _hq_time FROM _hq_source LIMIT 0)))) AS _hq_upper, toStartOfDay(_hq_lower) AS _hq_first, toStartOfDay(_hq_upper) AS _hq_last),
_hq_series AS (SELECT addDays(_hq_first, arrayJoin(range(toUInt64(dateDiff('day', _hq_first, _hq_last) + 1 + 0 + 0 + throwIf(arrayExists(_hq_calendar_index -> addDays(_hq_first, _hq_calendar_index + 1) <= addDays(_hq_first, _hq_calendar_index), range(toUInt64(greatest(1, dateDiff('day', _hq_first, _hq_last) + 1 + 0 + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.'))))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.') + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.'))))) AS _hq_period FROM _hq_bounds),
_hq_context0 AS (SELECT _hq_period, _hq_period AS _hq_eval_period, addDays(_hq_period, 1) AS _hq_eval_end, greatest(_hq_period, _hq_lower) AS _hq_eval_lower, least(addDays(_hq_period, 1), _hq_upper) AS _hq_eval_upper, (_hq_period > _hq_lower OR 1) AS _hq_lower_inclusive, (_hq_upper < addDays(_hq_period, 1) AND 1) AS _hq_upper_inclusive FROM _hq_series CROSS JOIN _hq_bounds),
_hq_history0 AS (SELECT * FROM _hq_source WHERE _hq_time < (SELECT max(_hq_eval_end) FROM _hq_context0)),
_hq_partial0 AS (SELECT _hq_time, _hq_d0, tuple(_hq_d0) AS _hq_partition, toNullable(sumOrNull(_hq_v0)) AS _hq_partial FROM _hq_history0 GROUP BY _hq_time, _hq_d0),
_hq_leaf0 AS (SELECT _hq_time, _hq_partition, sumOrNull(_hq_partial) OVER (PARTITION BY _hq_partition ORDER BY _hq_time ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS _hq_value0 FROM _hq_partial0),
_hq_ranges1 AS (SELECT _hq_period, _hq_eval_lower AS _hq_scan_lower, _hq_eval_upper AS _hq_scan_upper, _hq_lower_inclusive AS _hq_scan_lower_inclusive, _hq_upper_inclusive AS _hq_scan_upper_inclusive FROM _hq_context0),
_hq_keys1 AS (SELECT *, addDays(toStartOfDay(_hq_scan_lower), arrayJoin(range(toUInt64(greatest(0, dateDiff('day', toStartOfDay(_hq_scan_lower), toStartOfDay(_hq_scan_upper)) + if(_hq_scan_upper > toStartOfDay(_hq_scan_upper) OR _hq_scan_upper_inclusive, 1, 0)) + 0 + throwIf(arrayExists(_hq_calendar_index -> addDays(toStartOfDay(_hq_scan_lower), _hq_calendar_index + 1) <= addDays(toStartOfDay(_hq_scan_lower), _hq_calendar_index), range(toUInt64(greatest(1, greatest(0, dateDiff('day', toStartOfDay(_hq_scan_lower), toStartOfDay(_hq_scan_upper)) + if(_hq_scan_upper > toStartOfDay(_hq_scan_upper) OR _hq_scan_upper_inclusive, 1, 0)) + 0)))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.'))))) AS _hq_source_period FROM _hq_ranges1),
_hq_rows1 AS (SELECT r.*, b._hq_period FROM _hq_source AS r INNER JOIN _hq_keys1 AS b ON toStartOfDay(r._hq_time) = b._hq_source_period WHERE (r._hq_time > b._hq_scan_lower OR (b._hq_scan_lower_inclusive AND r._hq_time = b._hq_scan_lower)) AND (r._hq_time < b._hq_scan_upper OR (b._hq_scan_upper_inclusive AND r._hq_time = b._hq_scan_upper))),
_hq_leaf1 AS (SELECT _hq_period, _hq_d0, toNullable(count(_hq_v1)) AS _hq_value1 FROM _hq_rows1 GROUP BY _hq_period, _hq_d0),
_hq_skeleton AS (SELECT * FROM _hq_series CROSS JOIN (SELECT DISTINCT _hq_d0 FROM (SELECT _hq_d0 FROM _hq_history0 UNION ALL SELECT _hq_d0 FROM _hq_rows1)) AS _hq_combinations),
_hq_lookup0 AS (SELECT s.*, c._hq_eval_end, tuple(s._hq_d0) AS _hq_partition FROM _hq_skeleton AS s INNER JOIN _hq_context0 AS c ON s._hq_period = c._hq_period),
_hq_evaluated0 AS (SELECT s.* EXCEPT (_hq_eval_end, _hq_partition), m._hq_value0 AS _hq_value0 FROM _hq_lookup0 AS s LEFT ASOF JOIN _hq_leaf0 AS m ON s._hq_partition = m._hq_partition AND s._hq_eval_end > m._hq_time),
_hq_evaluated1 AS (SELECT s.*, coalesce(m._hq_value1, 0) AS _hq_value1 FROM _hq_evaluated0 AS s LEFT JOIN _hq_leaf1 AS m ON s._hq_period = m._hq_period AND isNotDistinctFrom(s._hq_d0, m._hq_d0)),
_hq_formula2 AS (SELECT *, (toFloat64(`_hq_value0`) / NULLIF(`_hq_value1`, 0)) AS `_hq_value2` FROM _hq_evaluated1),
_hq_formula3 AS (SELECT *, ROUND(`_hq_value2`, 2) AS `_hq_value3` FROM _hq_formula2),
_hq_values AS (SELECT v._hq_period AS period, v._hq_d0 AS `status`, v._hq_value3 AS `runningAovRounded` FROM _hq_formula3 AS v),
_hq_result AS (SELECT `period`, `status`, `runningAovRounded` FROM _hq_values UNION ALL SELECT NULL AS `period`, NULL AS `status`, NULL AS `runningAovRounded` FROM _hq_bounds WHERE 0 + 0 + throwIf(arrayExists(_hq_calendar_index -> addDays(_hq_first, _hq_calendar_index + 1) <= addDays(_hq_first, _hq_calendar_index), range(toUInt64(greatest(1, dateDiff('day', _hq_first, _hq_last) + 1 + 0 + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.'))))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.') + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.') + (SELECT coalesce(max(throwIf(arrayExists(_hq_calendar_index -> addDays(_hq_eval_period, _hq_calendar_index + 1) <= addDays(_hq_eval_period, _hq_calendar_index), range(toUInt64(greatest(1, 1)))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.')), 0) FROM _hq_context0) + 0 + 0 + (SELECT coalesce(max(0 + throwIf(arrayExists(_hq_calendar_index -> addDays(toStartOfDay(_hq_scan_lower), _hq_calendar_index + 1) <= addDays(toStartOfDay(_hq_scan_lower), _hq_calendar_index), range(toUInt64(greatest(1, greatest(0, dateDiff('day', toStartOfDay(_hq_scan_lower), toStartOfDay(_hq_scan_upper)) + if(_hq_scan_upper > toStartOfDay(_hq_scan_upper) OR _hq_scan_upper_inclusive, 1, 0)) + 0)))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.')), 0) FROM _hq_ranges1) = 1) SELECT `period`, `status`, `runningAovRounded` FROM _hq_result ORDER BY `period` ASC

